package fr.cercle.tourderole;
import android.app.*;import android.content.*;import android.os.*;import android.media.*;import android.media.session.*;import java.io.*;
public class AudioService extends Service{
public static MediaPlayer mp;public static String currentId="";String title="Audio";MediaSession session;AudioManager manager;AudioFocusRequest focus;Handler h=new Handler();public IBinder onBind(Intent i){return null;}
public void onCreate(){super.onCreate();manager=(AudioManager)getSystemService(AUDIO_SERVICE);session=new MediaSession(this,"CercleAudio");session.setCallback(new MediaSession.Callback(){public void onPlay(){if(mp!=null){mp.start();notifyPlayer();}}public void onPause(){if(mp!=null){mp.pause();notifyPlayer();}}public void onStop(){stop();}public void onSeekTo(long pos){seek((int)pos);}});session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setActive(true);h.post(tick);}
public int onStartCommand(Intent in,int flags,int start){if(in==null){stopSelf();return START_NOT_STICKY;}String a=in.getAction();try{if("play".equals(a)){if(mp!=null){remember();mp.release();}currentId=in.getStringExtra("id");title=in.getStringExtra("name");NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("audio","Lecture audio",NotificationManager.IMPORTANCE_LOW));startForeground(11,notification());File base=getFilesDir(),f=new File(base,in.getStringExtra("file"));if(!f.getCanonicalPath().startsWith(base.getCanonicalPath()+File.separator))throw new IOException("Chemin refusé");mp=new MediaPlayer();mp.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());mp.setDataSource(f.getPath());mp.setOnPreparedListener(p->{long startAt=in.getLongExtra("position",0);if(startAt<=0)startAt=getSharedPreferences("audio",0).getLong(currentId,0);p.seekTo((int)Math.min(startAt,p.getDuration()));focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(change->{if(mp!=null&&change<0){mp.pause();notifyPlayer();}}).build();if(manager.requestAudioFocus(focus)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED)p.start();notifyPlayer();});mp.setOnCompletionListener(p->{stop();getSharedPreferences("audio",0).edit().putLong(currentId,0).apply();});mp.setOnErrorListener((p,w,e)->{stop();return true;});mp.prepareAsync();}else if("toggle".equals(a)){if(mp!=null){if(mp.isPlaying())mp.pause();else mp.start();notifyPlayer();}else stopSelf();}else if("stop".equals(a))stop();}catch(Exception e){stop();}return START_NOT_STICKY;}
Notification notification(){PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent toggle=PendingIntent.getService(this,1,new Intent(this,AudioService.class).setAction("toggle"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE),stop=PendingIntent.getService(this,2,new Intent(this,AudioService.class).setAction("stop"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"audio").setSmallIcon(R.drawable.icon).setContentTitle(title).setContentText("Audio de poche · lecture locale").setContentIntent(open).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1)).addAction(new Notification.Action.Builder(null,"Lecture / pause",toggle).build()).addAction(new Notification.Action.Builder(null,"Arrêter",stop).build()).build();}
void notifyPlayer(){try{NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.notify(11,notification());if(mp!=null)session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_SEEK_TO|PlaybackState.ACTION_STOP).setState(mp.isPlaying()?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,mp.getCurrentPosition(),1).build());}catch(Exception ignored){}}
void remember(){try{if(mp!=null)getSharedPreferences("audio",0).edit().putLong(currentId,mp.getCurrentPosition()).apply();}catch(Exception ignored){}}
Runnable tick=new Runnable(){public void run(){remember();h.postDelayed(this,5000);}};
public static void jump(int delta){try{if(mp!=null)seek(mp.getCurrentPosition()+delta);}catch(Exception ignored){}}public static void seek(int pos){try{if(mp!=null)mp.seekTo(Math.max(0,Math.min(pos,mp.getDuration())));}catch(Exception ignored){}}public static void speed(float s){try{if(mp!=null)mp.setPlaybackParams(new PlaybackParams().setSpeed(s));}catch(Exception ignored){}}
void stop(){remember();if(mp!=null){mp.release();mp=null;}stopForeground(true);stopSelf();}public void onDestroy(){remember();if(mp!=null){mp.release();mp=null;}h.removeCallbacksAndMessages(null);if(session!=null)session.release();if(focus!=null)manager.abandonAudioFocusRequest(focus);super.onDestroy();}
}
